        if (node1 == null && node2 == null) {
            return true;
        }
        if (node1 == null || node2 == null) {
            return false;
        }
        return test(node1.esq, node2.esq) && test(node1.dir, node2.dir);
    }

    static class Node {

        private Integer valor;
        private Node esq;
        private Node dir;

        Node() {}

        void add(int valor) {
            if (this.valor == null) {
                this.valor = valor;
                this.esq = new Node();
                this.dir = new Node();
            }
            else if (this.valor > valor) this.esq.add(valor);
            else this.dir.add(valor);
        }
    }
}

