import java.util.Scanner;

/**
 * Represents a node in the binary tree.
 */
class Node {
    int value;
    Node left;
    Node right;

    Node(int value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }
}

/**
 * Represents the Binary Search Tree and its operations.
 */
class BinarySearchTree {
    Node root;

    BinarySearchTree() {
        this.root = null;
    }

    /**
     * Public method to insert a value. It calls the recursive helper method.
     * @param value The integer value to insert.
     */
    public void insert(int value) {
        root = insertRec(root, value);
    }

    /**
     * A recursive function to insert a new value into the BST.
     * @param current The current node in the recursion.
     * @param value The value to insert.
     * @return The node after insertion.
     */
    private Node insertRec(Node current, int value) {
        // If the tree or subtree is empty, create a new node.
        if (current == null) {
            return new Node(value);
        }

        // Recur down the tree.
        if (value < current.value) {
            current.left = insertRec(current.left, value);
        } else if (value > current.value) {
            current.right = insertRec(current.right, value);
        }
        // If value is equal to current.value, do nothing (as per standard BST behavior).

        return current;
    }
}

