public class Solution {

    /**
     * Inserts a value into a binary search tree recursively.
     * @param current The current node being considered for insertion.
     * @param value The integer value to insert.
     * @return The root of the modified subtree.
     */
    public static Node insert(Node current, int value) {
        // If the tree/subtree is empty, create a new node and return it.
        if (current == null) {
            return new Node(value);
        }

        // Otherwise, recur down the tree.
        if (value < current.value) {
            current.left = insert(current.left, value);
        } else if (value > current.value) {
            current.right = insert(current.right, value);
