import java.util.Scanner;
import java.util.ArrayList;
import java.util.Arrays;

// Classe para representar um nó
da árvore
class Node {
    int value;
    Node left;
    Node right;

    Node(int value) {
        this.value = value;
        left = null;
        right = null;
    }
}

// Classe para a Árvore Binária de Busca (BST)
class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    // Método para adicionar um novo valor na árvore
    public void add(int value) {
        this.root = addRecursive(this.root, value);
    }

    private Node addRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = addRecursive(current.left, value);
        } else if (value > current.value) {
            current.right = addRecursive(current.right, value);
        }
        // Não faz nada se o valor já existir, conforme o prompt

        return current;
    }

    // Método para obter o percurso em pré-ordem
    public void preOrder(ArrayList<Integer> list) {
        preOrderRecursive(this.root, list);
    }

    private void preOrderRecursive(Node node, ArrayList<Integer> list) {
        if (node != null) {
            list.add(node.value);
            preOrderRecursive(node.left, list);
            preOrderRecursive(node.right, list);
        }
    }

    // Método para contar elementos menores que N
    public int countSmaller(int n) {
        return countSmallerRecursive(this.root, n);
    }

    private int countSmallerRecursive(Node node, int n) {
        if (node == null) {
            return 0;
        }

        // Se o valor do nó atual é menor que N
        if (node.value < n) {
            // Contamos este nó, todos os nós à sua esquerda (que são garantidamente menores)
            // e continuamos a busca na subárvore direita.
            return 1 + countNodes(node.left) + countSmallerRecursive(node.right, n);
        } else { // Se o valor do nó atual é >= N
            // Nenhum nó na subárvore direita será menor que N, e o nó atual também não é.
            // Portanto, só precisamos procurar na subárvore esquerda.
            return countSmallerRecursive(node.left, n);
        }
    }

    // Método auxiliar para contar todos os nós em uma subárvore
    private int countNodes(Node node) {
        if (node == null) {
            return 0;
        }
        return 1 + countNodes(node.left) + countNodes(node.right);
    }
}

// Classe principal da solução
public class Solution {
