import java.util.Scanner;
import java.util.ArrayList;
import java.util.Arrays;

// Classe para representar um nó da árvore
class Node {
    int value;
    Node left;
    Node right;

    Node(int value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }
}

// Classe para representar a Árvore Binária de Pesquisa (BST)
class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    // Método para adicionar um valor à árvore
    public void add(int value) {
        this.root = addRecursive(this.root, value);
    }

    private Node addRecursive(Node current, int value) {
        if (current == null) {
            return new Node(value);
        }

        if (value < current.value) {
            current.left = addRecursive(current.left, value);
        } else if (value > current.value) {
            current.right = addRecursive(current.right, value);
        }
        // O valor já existe, não faz nada (conforme premissa de não haver repetidos)
        return current;
    }

    // Método para encontrar o valor mais próximo de N com complexidade O(h)
    public int findClosestValue(int target) {
        if (this.root == null) {
            throw new IllegalStateException("A árvore está vazia.");
        }

        Node current = this.root;
        int closest = current.value;

        while (current != null) {
            // Atualiza o valor mais próximo se o nó atual for mais próximo do que o já registrado
            if (Math.abs(target - current.value) < Math.abs(target - closest)) {
                closest = current.value;
            }

            // Se o valor exato for encontrado, a distância é 0, que é a menor possível.
            if (target == current.value) {
                return current.value;
            }

            // Decide para qual subárvore descer, aproveitando a propriedade da BST
            if (target < current.value) {
                current = current.left;
            } else {
                current = current.right;
            }
        }
        return closest;
    }

    // Método para gerar o percurso em pré-ordem
    public void preOrder(ArrayList<Integer> list) {
        preOrderRecursive(this.root, list);
    }

    private void preOrderRecursive(Node node, ArrayList<Integer> list) {
        if (node != null) {
            list.add(node.value);
            preOrderRecursive(node.left, list);
            preOrderRecursive(node.right, list);
        }
    }
}

// Classe principal para execução do programa
public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Lê a primeira linha e constrói a árvore
        String[] elementsStr = scanner.nextLine().split(" ");
        BST tree = new BST();
        for (String s : elementsStr) {
            tree.add(Integer.parseInt(s));
        }

        // Lê o valor de N
        int n = scanner.nextInt();
        scanner.close();

        // Imprime o percurso em pré-ordem
        ArrayList<Integer> preOrderList = new ArrayList<>();
        tree.preOrder(preOrderList);
        System.out.println(Arrays.toString(preOrderList.toArray()));

        // Encontra e imprime o valor mais próximo
        int closestValue = tree.findClosestValue(n);
        System.out.println(closestValue);
    }
}
