    /**
     * Aplica o algoritmo Radix Sort para ordenar o array de placas com base
     * em sua parte numérica de 4 dígitos.
     * @param arr O array de placas a ser ordenado.
     */
    private static void radixSort(String[] arr) {
        // A placa tem formato AAA-9999, com 8 caracteres.
        // Os dígitos numéricos estão nos índices 4, 5, 6, 7.
        int ultimoIndiceDigito = 7;
        int primeiroIndiceDigito = 4;

        // Itera do dígito menos significativo (índice 7) ao mais significativo (índice 4).
        for (int i = ultimoIndiceDigito; i >= primeiroIndiceDigito; i--) {
