     * utilizando o algoritmo Counting Sort.
     * @param arr O array de placas.
     * @param indiceDigito O índice do caractere (dígito) a ser usado para a ordenação.
     */
    private static void countingSortPorDigito(String[] arr, int indiceDigito) {
        int n = arr.length;
        String[] saida = new String[n];
        int[] contagem = new int[10]; // Para os dígitos de 0 a 9

        // Passo 1: Contar a frequência de cada dígito.
        for (int i = 0; i < n; i++) {
            int digito = Character.getNumericValue(arr[i].charAt(indiceDigito));
            contagem[digito]++;
        }

        // Passo 2: Modificar o array de contagem para que cada elemento
        // armazene a posição final do dígito no array de saída.
        for (int i = 1; i < 10; i++) {
            contagem[i] += contagem[i - 1];
        }

        // Passo 3: Construir o array de saída. Iterar de trás para frente
        // para manter a estabilidade do algoritmo.
        for (int i = n - 1; i >= 0; i--) {
            int digito = Character.getNumericValue(arr[i].charAt(indiceDigito));
            saida[contagem[digito] - 1] = arr[i];
            contagem[digito]--;
        }

        // Passo 4: Copiar o array de saída ordenado de volta para o array original.
        System.arraycopy(saida, 0, arr, 0, n);
    }
}
