class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputLine = scanner.nextLine();
        String[] plates = inputLine.split(",");
        scanner.close();

        // A parte numérica da placa "AAA-9999" está nos índices 4, 5, 6 e 7.
        // O Radix Sort (LSD - Least Significant Digit) começa pelo dígito menos significativo (índice 7)
        // e vai até o mais significativo (índice 4).
        final int mostSignificantDigitIndex = 4;
        final int leastSignificantDigitIndex = 7;

        for (int i = leastSignificantDigitIndex; i >= mostSignificantDigitIndex; i--) {
            plates = countingSortByDigit(plates, i);
        }

        // Imprime o array ordenado no formato exigido, usando String.join para eficiência e clareza.
        System.out.println(String.join(", ", plates));
    }

    /**
     * Realiza uma ordenação estável (Counting Sort) em um array de placas com base
     * no dígito em um índice específico.
     *
     * @param inputArray O array de placas a ser ordenado.
     * @param digitIndex O índice do caractere (dígito) a ser usado para a ordenação.
     * @return Um novo array com as placas ordenadas.
     */
    private static String[] countingSortByDigit(String[] inputArray, int digitIndex) {
        int n = inputArray.length;
        String[] outputArray = new String[n];
        int[] count = new int[10]; // Para os dígitos de 0 a 9

        // 1. Armazena a contagem de ocorrências de cada dígito.
        for (String plate : inputArray) {
            // Character.getNumericValue é uma forma robusta de converter um char '0'-'9' para int 0-9.
            int digit = Character.getNumericValue(plate.charAt(digitIndex));
            count[digit]++;
        }

        // 2
. Modifica a contagem para que cada elemento em `count[i]` armazene a posição final
        // correta do dígito `i` no array de saída.
        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        // 3. Constrói o array de saída. A iteração reversa garante a estabilidade.
        for (int i = n - 1; i >= 0; i--) {
            String plate = inputArray[i];
            int digit = Character.getNumericValue(plate.charAt(digitIndex));

            // Coloca a placa na posição correta no array de saída.
            outputArray[count[digit] - 1] = plate;

            // Decrementa a contagem para a próxima placa com o mesmo dígito.
            count[digit]--;
        }

        return outputArray;
    }
}
