A estratégia mais eficiente para extrair o trio de dígitos em cada passo é usar operações aritméticas com potências de 10. Por exemplo, para extrair o trio do meio do número `784367437`, podemos fazer `(784367437 / 1000) % 1
### Minha Resposta

```java
import java.util.Arrays;
import java.util.Scanner;

public class RadixTresDigitos {

    /**
     * Ordena um array usando o Counting Sort com base em um trio de dígitos específico.
     *
     * @param arr O array a ser ordenado.
     * @param exp O expoente (potência de 10) usado para determinar qual trio de dígitos usar.
     *            (exp=1 para o primeiro trio, exp=1000 para o segundo, etc.)
     */
    public static void countingSortPorTrio(int[] arr, int exp) {
        int n = arr.length;
        int[] output = new int[n]; // Array de saída que terá os números ordenados
        int[] count = new int[1000]; // Os trios de dígitos vão de 000 a 999

        // Inicializa o array de contagem com zeros
        Arrays.fill(count, 0);

        // Armazena a contagem de ocorrências em count[]
        // A expressão (arr[i] / exp) % 1000 extrai o trio de dígitos relevante.
        for (int i = 0; i < n; i++) {
            int trioIndex = (arr[i] / exp) % 1000;
            count[trioIndex]++;
        }

        // Altera count[i] para que contenha a posição final real
        // deste dígito no array de saída (soma cumulativa).
        for (int i = 1; i < 1000; i++) {
            count[i] += count[i - 1];
        }

        // Constrói o array de saída.
        // Iterar de trás para frente mantém a estabilidade do algoritmo.
        for (int i = n - 1; i >= 0; i--) {
            int trioIndex = (arr[i] / exp) % 1000;
            output[count[trioIndex] - 1] = arr[i];
            count[trioIndex]--;
        }

