import java.util.Scanner;
import java.util.Queue;
import java.util.LinkedList;

// The prompt implies the main class should be named Solution.
public class Solution {

    // Inner class for a tree node
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    // Inner class for the Binary Search Tree
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        // Method to add a new value to the tree
        public void add(int value) {
            this.root = addRecursive(this.root, value);
        }

        // Recursive helper for adding a node
        private Node addRecursive(Node current, int value) {
            if (current == null) {
                return new Node(value);
            }

            if (value < current.value) {
                current.left = addRecursive(current.left, value);
            } else if (value > current.value) {
                current.right = addRecursive(current.right, value);
            }
            // Value already exists, do nothing as per prompt assumption.

            return current;
        }

        // Method to perform BFS from right to left and print the result
        public void bfsRightToLeft() {
            if (this.root == null) {
                return;
            }

            Queue<Node> queue = new LinkedList<>();
            queue.add(this.root);
            StringBuilder result = new StringBuilder();

            while (!queue.isEmpty()) {
                Node currentNode = queue.poll();

                if (result.length() > 0) {
                    result.append(" ");
                }
                result.append(currentNode.value);

                // To traverse right-to-left, add the right child first, then the left.
                if (currentNode.right != null) {
                    queue.add(currentNode.right);
                }
                if (currentNode.left != null) {
                    queue.add(currentNode.left);
                }
            }
            System.out.println(result.toString());
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] inputNumbers = scanner.nextLine().split(" ");

        BST tree = new BST();
        for (String numStr : inputNumbers) {
            if (!numStr.isEmpty()) { // Handle potential extra spaces
                tree.add(Integer.parseInt(numStr));
            }
        }

        tree.bfsRightToLeft();
        scanner.close();
    }
}
