class HashSet {
    private Integer[] table;
    private final int capacity;
    private int size;
    // Objeto sentinela para marcar posições removidas (tombstone)
    private static final Integer DELETED = new Integer(Integer.MIN_VALUE);

    public HashSet(int capacity) {
        this.capacity = capacity;
        this.table = new Integer[capacity];
        this.size = 0;
    }

    private int hash(int key) {
        // Garante que o resultado seja sempre positivo
        return (key % capacity + capacity) % capacity;
    }

    public void put(int value) {
        // Se o conjunto já contém o valor, não faz nada, mas imprime o estado.
        if (contains(value)) {
            return;
        }

        // Se a tabela está cheia, não insere, mas imprime o estado.
        if (size == capacity) {
            return;
        }

        int i = 0;
        while (i < capacity) {
            int index = (hash(value) + i) % capacity;
            // Encontra uma posição vazia (null) ou previamente removida (DELETED)
            if (table[index] == null || table[index] == DELETED) {
                table[index] = value;
                size++;
                return;
            }
            i++;
        }
    }

    public void remove(int value) {
        int i = 0;
        while (i < capacity) {
            int index = (hash(value) + i) % capacity;
            // Se encontrar uma posição nula, o elemento não existe na cadeia de probing.
            if (table[index] == null) {
                return; // Valor não encontrado
            }
            // Se encontrar o valor, marca a posição como DELETED.
            if (table[index].equals(value)) {
                table[index] = DELETED;
                size--;
                return;
            }
            i++;
        }
    }

    public boolean contains(int value) {
        int i = 0;
        while (i < capacity) {
            int index = (hash(value) + i) % capacity;
            // Se encontrar uma posição nula, o elemento não existe na cadeia de probing.
            if (table[index] == null) {
                return false;
            }
            // Se encontrar o valor, retorna true.
            if (table[index].equals(value)) {
                return true;
            }
            // Se encontrar uma posição DELETED, a busca deve continuar.
            i++;
        }
        return false;
    }

    @Override
