```java
import java.util.Scanner;
import java.util.Arrays;

class Solution {

    /**
     * Troca dois elementos de posição em um array.
     * @param arr O array.
     * @param i O índice do primeiro elemento.
     * @param j O índice do segundo elemento.
     */
    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Particiona o array em torno do primeiro elemento (pivô).
     * Ao final, todos os elementos menores que o pivô estarão à sua esquerda
     * e todos os maiores estarão à sua direita.
     * @param arr O array a ser particionado.
     * @return A estatística de ordem do pivô original (sua posição final + 1).
     */
    public static int partitionAndGetOrderStatistic(int[] arr) {
        // O primeiro elemento é o pivô.
        int pivot = arr[0];

        // 'i' marca a fronteira onde os elementos menores que o pivô terminam.
        // Começamos com 'i' em 1, pois o pivô está na posição 0.
        int i = 1; 

        // Percorremos o resto do array a partir do segundo elemento.
        for (int j = 1; j < arr.length; j++) {
            // Se encontramos um elemento menor que o pivô...
            if (arr[j] < pivot) {
                // ...o movemos para a seção de "menores", trocando-o com o elemento
                // na fronteira 'i', e então avançamos a fronteira.
                swap(arr, i, j);
                i++;
            }
        }

        // Ao final do loop, a posição correta do pivô é 'i - 1'.
        // Trocamos o pivô (que ainda está em arr[0]) com o elemento em arr[i - 1].
        swap(arr, 0, i - 1);

        // A estatística de ordem é a posição final do pivô (i - 1) mais 1.
        // Portanto, a estatística de ordem é 'i'.
        return i;
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String input = scan.nextLine();

        String[] strArray = input.split(" ");
        int[] intArray = new int[strArray.length];
        for(int i = 0; i < strArray.length; i++) {
            intArray[i] = Integer.parseInt(strArray[i]);
        }

        // Chama a função que particiona o array e retorna a estatística de ordem.
        int orderStatistic = partitionAndGetOrderStatistic(intArray);

        System.out.println(orderStatistic);

        // Opcional: Descomente a linha abaixo para verificar o estado final do array
        // e confirmar que ele foi particionado corretamente.
        // System.out.println("Array particionado: " + Arrays.toString(intArray));
    }
}
```

