    /**
     * Represents the Binary Search Tree.
     */
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        /**
         * Adds a new value to the BST.
         * @param value The integer value to add.
         */
        public void add(int value) {
            root = addRecursive(root, value);
        }

        private Node addRecursive(Node current, int value) {
            if (current == null) {
                return new Node(value);
            }

            if (value < current.value) {
                current.left = addRecursive(current.left, value);
            } else if (value > current.value) {
                // The prompt assumes no duplicates, so we only handle greater than.
                current.right = addRecursive(current.right, value);
            }

            return current;
        }

        /**
         * Finds the minimum value in the BST and prints the path from the root to it.
         * In a BST, the minimum value is the leftmost node.
         */
        public void printPathToMin() {
            if (root == null) {
                // The prompt guarantees at least one element, so this case won't be hit.
                return;
            }

            Node current = root;
            StringBuilder path = new StringBuilder();

            while (current != null) {
                path.append(current.value);
                if (current.left != null) {
                    path.append(" ");
                }
                current = current.left;
            }
