 */
public class Solution {

    private Node root;

    public Solution() {
        this.root = null;
    }

    /**
     * Insere um novo valor na BST de forma iterativa.
     * @param value O valor a ser inserido.
     */
    public void insert(int value) {
        if (this.root == null) {
            this.root = new Node(value);
            return;
        }

        Node current = this.root;
        while (true) {
            if (value < current.value) {
                if (current.left == null) {
                    current.left = new Node(value);
                    return;
                }
                current = current.left;
            } else { // value > current.value, pois não há elementos repetidos
                if (current.right == null) {
                    current.right = new Node(value);
                    return;
                }
                current = current.right;
            }
        }
    }

    /**
     * Realiza o percurso em largura (BFS) e imprime o resultado.
     */
    public void breadthFirstSearch() {
        if (root == null) {
            System.out.println(""); // Imprime linha vazia se a árvore estiver vazia
            return;
        }

        Queue<Node> queue = new LinkedList<>();
        queue.add(root);

        StringBuilder output = new StringBuilder();

        while (!queue.isEmpty()) {
            Node currentNode = queue.poll();

            if (output.length() > 0) {
                output.append(" ");
            }
            output.append(currentNode.value);

            if (currentNode.left != null) {
                queue.add(currentNode.left);
            }
            if (currentNode.right != null) {
                queue.add(currentNode.right);
            }
        }
        System.out.println(output.toString());
    }

