        Scanner scanner = new Scanner(System.in);
        String[] inputValues = scanner.nextLine().split(" ");

        Solution bst = new Solution();

        for (String valueStr : inputValues) {
            if (!valueStr.isEmpty()) {
                bst.insert(Integer.parseInt(valueStr));
            }
        }

        scanner.close();

        bst.breadthFirstSearch();
    }
}
