    /**
     * Verifica se um array de inteiros possui elementos duplicados usando uma abordagem de força bruta.
     * Esta abordagem tem uma complexidade de tempo de O(n^2) e de espaço de O(1).
     * É a mais robusta pois funciona para qualquer intervalo de números (positivos, negativos, zero)
     * sem risco de estourar a memória.
     *
     * @param array O array de inteiros a ser verificado.
     * @return true se houver elementos duplicados, false caso contrário.
     */
    public static boolean possuiDuplicados(int[] array) {
        // Um array com 0 ou 1 elemento não pode ter duplicados.
        if (array.length < 2) {
            return false;
        }

        // Compara cada elemento com todos os elementos que vêm depois dele.
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                // Se encontrar dois elementos iguais, retorna true.
                if (array[i] == array[j]) {
                    return true;
                }
            }
        }

        // Se o loop terminar sem encontrar duplicados, retorna false.
        return false;
    }
}
