        String[] inputStrings = sc.nextLine().split(" ");
        sc.close();

        // Conversão da entrada de String[] para int[]
        int[] array = new int[inputStrings.length];
        for (int i = 0; i < inputStrings.length; i++) {
            array[i] = Integer.parseInt(inputStrings[i]);
        }

        // Caso o array seja vazio ou tenha apenas um elemento, não há o que particionar.
        if (array.length <= 1) {
            System.out.println(Arrays.toString(array));
            return;
        }

        // Chama o método de particionamento e armazena o resultado
        int[] resultado = particiona(array);

        // Imprime o resultado formatado
        System.out.println(Arrays.toString(resultado));
