    /**
     * Particiona o array usando o primeiro elemento como pivô, mantendo a ordem relativa (estável).
     * @param array O array de inteiros a ser particionado.
     * @return Um novo array com os elementos particionados.
     */
    public static int[] particiona(int[] array) {
        int pivot = array[0];
        int[] resultado = new int[array.length];
        int indiceResultado = 0;

        // 1. Primeira passagem: Adiciona todos os elementos menores ou iguais ao pivô.
        // A iteração começa em 1 para pular o próprio pivô.
        for (int i = 1; i < array.length; i++) {
            if (array[i] <= pivot) {
                resultado[indiceResultado] = array[i];
                indiceResultado++;
            }
        }

        // 2. Adiciona o pivô na sua posição correta.
        resultado[indiceResultado] = pivot;
        indiceResultado++;

        // 3. Segunda passagem: Adiciona todos os elementos maiores que o pivô.
        for (int i = 1; i < array.length; i++) {
            if (array[i] > pivot) {
                resultado[indiceResultado] = array[i];
                indiceResultado++;
            }
        }

        return resultado;
    }
