    @SuppressWarnings("unchecked")
    public TabelaHash(int M) {
        this.M = M;
        // The unchecked cast is necessary because Java doesn't allow generic array creation directly.
        this.table = (ArrayList<Pair>[]) new ArrayList[M];
        for (int i = 0; i < M; i++) {
