// A classe principal é nomeada 'Solution' para corresponder ao exemplo de execução.
public class Solution {

    // Classe interna para representar um nó da árvore.
    static class Node {
        int value;
        Node left;
        Node right;

        Node(int value) {
            this.value = value;
            this.left = null;
            this.right = null;
        }
    }

    // Classe interna para a Árvore Binária de Pesquisa (BST).
    static class BST {
        private Node root;

        public BST() {
            this.root = null;
        }

        /**
         * Adiciona um valor à árvore de forma iterativa.
         * @param value O valor a ser adicionado.
         */
        public void add(int value) {
            if (this.root == null) {
                this.root = new Node(value);
                return;
            }

            Node current = this.root;
            while (true) {
                // Valores menores vão para a esquerda.
                if (value < current.value) {
                    if (current.left == null) {
                        current.left = new Node(value);
                        return;
                    }
                    current = current.left;
                } 
                // Valores maiores vão para a direita (não há duplicados).
                else {
                    if (current.right == null) {
                        current.right = new Node(value);
                        return;
                    }
                    current = current.right;
                }
            }
        }

        /**
         * Imprime o caminho da raiz até o elemento de valor máximo.
         * Em uma BST, o valor máximo é sempre o nó mais à direita.
         */
        public void printMaxPath() {
            if (this.root == null) {
                return; // A árvore está vazia.
            }

            // StringJoiner é uma forma eficiente de construir uma string com delimitadores.
            StringJoiner path = new StringJoiner(" ");
            Node current = this.root;
            while (current != null) {
                path.add(String.valueOf(current.value));
                current = current.right;
            }
            System.out.println(path.toString());
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Lê a linha de entrada e a divide em um array de strings.
        String[] inputValues = scanner.nextLine().split(" ");

        BST tree = new BST();

        // Itera sobre os valores, converte para inteiro e adiciona à árvore.
        for (String valStr : inputValues) {
            tree.add(Integer.parseInt(valStr));
        }

        // Chama o método para imprimir o caminho até o máximo.
        tree.printMaxPath();

        scanner.close();
    }
}
